@import url('https://fonts.googleapis.com/css2?family=DM+Sans:wght@400;500;600;700&family=Playfair+Display:wght@600;700&display=swap');
:root{--ink:#f4efe4;--muted:#9daaa1;--bg:#061717;--panel:#0b2523;--panel2:#0e2d29;--line:#22453d;--gold:#e5b968;--coral:#df795e;--mint:#76c2a2}*{box-sizing:border-box}body{margin:0;background:radial-gradient(circle at 70% 0,#123d35 0,#071b1a 42%,#041010 100%);color:var(--ink);font-family:'DM Sans',sans-serif;min-height:100vh}.game-shell{max-width:1180px;margin:auto;padding:28px 28px 26px}.topbar{display:flex;justify-content:space-between;align-items:center;margin-bottom:22px}.brand{display:flex;gap:12px;align-items:center}.brand-mark{width:37px;height:37px;border:1px solid #6d947e;border-radius:12px;display:grid;place-items:center;color:var(--gold);font-size:20px;background:#102e28}.brand h1{font:700 22px 'Playfair Display',serif;letter-spacing:.2px;margin:0}.brand p{font-size:10px;text-transform:uppercase;letter-spacing:1.6px;color:#91aaa0;margin:3px 0 0}.day-block{display:flex;gap:10px;align-items:center}.day-block strong{display:block;font-size:12px;color:#ece3d1}.day-block small{color:#8aa097;font-size:10px}.day-block>span{width:9px;height:9px;background:var(--gold);border-radius:50%;box-shadow:0 0 11px var(--gold)}.game-layout{display:grid;grid-template-columns:minmax(0,1.55fr) minmax(310px,.85fr);gap:20px}.world-card,.side-panel>div{background:rgba(9,31,29,.9);border:1px solid var(--line);border-radius:15px}.world-card{overflow:hidden}.canvas-wrap{position:relative;background:#173c36;aspect-ratio:1.5;min-height:380px}.canvas-wrap canvas{width:100%;height:100%;display:block;image-rendering:auto}.toast{position:absolute;left:50%;top:18px;transform:translate(-50%,-10px);opacity:0;background:#f4e3ba;color:#18302a;border-radius:20px;padding:9px 16px;font-weight:700;font-size:12px;transition:.3s;pointer-events:none;white-space:nowrap;box-shadow:0 5px 20px #0005}.toast.show{opacity:1;transform:translate(-50%,0)}.controls-row{height:92px;display:flex;align-items:center;justify-content:space-between;padding:12px 23px}.dpad button{color:#cddacf;background:#12332f;border:1px solid #29554a;width:31px;height:27px;border-radius:7px;font-size:12px;margin:2px;box-shadow:0 2px #071816}.dpad>button{display:block;margin:auto}.dpad button:active{transform:translateY(2px);background:#285b4c}.action-hint{font-size:11px;color:#788f87;display:flex;align-items:center;gap:9px}.keycap{border:1px solid #59776b;padding:5px 7px;border-radius:6px;color:var(--gold);font-weight:bold;font-size:12px}.side-panel{display:flex;flex-direction:column;gap:12px}.side-panel>div{padding:15px 16px}.player-card{display:flex;align-items:center;gap:11px}.avatar{width:43px;height:43px;background:#c87a5b;border-radius:13px;display:grid;place-items:center;font-size:23px;border:2px solid #e6b778}.player-meta{flex:1}.player-meta strong{display:block;font:700 17px 'Playfair Display',serif}.player-meta span{color:#93a69d;font-size:10px}.xp{height:4px;background:#23453c;border-radius:5px;margin:7px 0 3px}.xp i,.meter i,.progress-line i{height:100%;display:block;background:var(--gold);border-radius:5px;width:0;transition:.4s}.player-meta small{font-size:9px;color:#839a90}.level{text-align:center;border-left:1px solid #2a4b41;padding-left:13px;color:var(--gold)}.level small{display:block;font-size:8px;letter-spacing:1px}.level b{font:700 24px 'Playfair Display',serif}.stats{display:grid;grid-template-columns:1.4fr 1fr 1fr;gap:12px;padding:12px 13px!important}.stats>div{position:relative;padding-left:25px;border-right:1px solid #24463d}.stats>div:last-child{border:0}.stat-icon{position:absolute;left:0;top:2px;font-size:17px;color:var(--gold)}.stat-icon.energy{color:#e5b968}.stat-icon.coins{color:#cf8b71}.stat-icon.rep{color:#76c2a2}.stats small{display:block;color:#80968d;font-size:8px;letter-spacing:1px}.stats strong{font-size:13px;display:block;margin-top:3px}.meter{height:4px;background:#25473e;margin-top:7px;border-radius:4px}.meter i{background:#e5b968;width:100%}.mission-card{border-color:#765b36!important;background:linear-gradient(120deg,#1d342b,#102821)!important}.section-title{display:flex;align-items:center;justify-content:space-between;color:#809c8d;letter-spacing:1.4px;font-size:9px;font-weight:700}.section-title>b{color:var(--gold);font-size:18px}.mission-card h2{font:700 17px 'Playfair Display',serif;margin:13px 0 5px}.mission-card p{color:#9eaca1;font-size:11px;line-height:1.45;margin:0 0 14px}.progress-line{height:5px;border-radius:4px;background:#3a4938}.progress-line i{background:#d98167}.quest-foot{display:flex;justify-content:space-between;margin-top:8px;font-size:10px;color:#a8ada0}.quest-foot b{color:var(--gold)}.section-title button{background:none;border:0;color:#9eb4a7;font-size:9px;letter-spacing:1px;cursor:pointer}.section-title button b{font-size:17px;color:var(--gold);vertical-align:-2px}.item-grid{display:flex;gap:9px;margin-top:13px}.item{width:42px;height:42px;border-radius:10px;background:#193a34;border:1px solid #2d574b;display:grid;place-items:center;font-size:21px;position:relative}.item small{position:absolute;bottom:-4px;right:-4px;background:#d9886d;color:#fff;border-radius:7px;padding:1px 5px;font-size:9px}.tip{display:flex;gap:10px;align-items:flex-start!important;background:#102e29!important;border-style:dashed!important}.tip>span{font-size:22px}.tip p{font-size:10px;line-height:1.4;color:#9baea3;margin:0}.tip b{color:#e4c487;font-weight:600}.bottom-nav{display:none}.modal{position:fixed;inset:0;background:#03100ecc;display:grid;place-items:center;z-index:10;padding:18px}.modal.hidden{display:none}.modal-box{position:relative;background:#0d2925;border:1px solid #356052;box-shadow:0 15px 60px #0008;border-radius:18px;width:min(460px,100%);padding:28px}.close{position:absolute;right:17px;top:13px;border:0;background:none;color:#b8c8bc;font-size:26px;cursor:pointer}.eyebrow{font-size:9px;letter-spacing:2px;color:var(--gold);font-weight:bold}.modal-box h2{font:700 25px 'Playfair Display',serif;margin:5px 0 20px}.full-items{display:grid;grid-template-columns:repeat(3,1fr);gap:10px}.full-items .item{width:auto;height:80px}.full-items .item span{font-size:28px}.modal-note{color:#8ea49a;font-size:11px;margin-bottom:0}.journal-entry{display:flex;gap:14px;padding:13px 0;border-top:1px solid #24483f}.journal-entry>span{color:var(--gold);font:700 18px 'Playfair Display',serif}.journal-entry b{font-size:13px}.journal-entry p{font-size:11px;color:#9caea5;line-height:1.45;margin:4px 0}.locked{opacity:.5}.help-list{padding-left:19px;color:#a6b6aa;font-size:12px;line-height:2}.help-list b{color:#e2c483}
@media(max-width:800px){.game-shell{padding:17px 14px 80px}.topbar{margin-bottom:13px}.game-layout{display:block}.side-panel{margin-top:12px;display:grid;grid-template-columns:1fr 1fr;gap:10px}.side-panel .player-card,.side-panel .stats,.side-panel .mission-card{grid-column:span 2}.side-panel .tip{display:none}.canvas-wrap{min-height:0}.controls-row{height:76px;padding:9px 16px}.bottom-nav{position:fixed;display:flex;bottom:0;left:0;right:0;height:64px;background:#09201e;border-top:1px solid #285248;z-index:5;justify-content:space-around;padding-bottom:env(safe-area-inset-bottom)}.bottom-nav button{background:none;border:0;color:#80968c;font-size:10px;display:flex;flex-direction:column;gap:3px;align-items:center;padding:8px 18px}.bottom-nav button span{font-size:20px}.bottom-nav button.active{color:var(--gold)}.inventory-card{grid-column:span 2}.action-hint{display:none}}@media(max-width:430px){.brand h1{font-size:19px}.day-block{font-size:11px}.side-panel{grid-template-columns:1fr}.side-panel .player-card,.side-panel .stats,.side-panel .mission-card,.inventory-card{grid-column:auto}.side-panel .stats{grid-template-columns:1.4fr 1fr 1fr}.canvas-wrap{aspect-ratio:1.2}.tip{display:none!important}}

const canvas=document.getElementById('gameCanvas'),ctx=canvas.getContext('2d');let W=900,H=600,dpr=1;const state={x:450,y:470,speed:3.1,energy:5,maxEnergy:5,xp:0,level:1,coins:24,respect:1,day:1,quest:0,items:{'🕯️':2,'🧹':1,'🌿':3,'🪙':4}};const keys={};const spots=[{x:185,y:160,type:'candle',emoji:'🕯️',label:'Vela de Doña Ana',done:false},{x:407,y:230,type:'clean',emoji:'🧹',label:'Sendero de los recuerdos',done:false},{x:680,y:150,type:'candle',emoji:'🕯️',label:'Vela del abuelo Juan',done:false},{x:725,y:390,type:'water',emoji:'🌿',label:'Jardín de ofrendas',done:false},{x:270,y:390,type:'candle',emoji:'🕯️',label:'Vela de la familia Cruz',done:false}];let last=0,toastTimer;
function resize(){const r=canvas.getBoundingClientRect();dpr=Math.min(2,devicePixelRatio||1);canvas.width=r.width*dpr;canvas.height=r.height*dpr;W=r.width;H=r.height;ctx.setTransform(dpr,0,0,dpr,0,0)}function sx(v){return v*W/900}function sy(v){return v*H/600}function draw(){ctx.clearRect(0,0,W,H);ctx.save();ctx.scale(W/900,H/600);drawWorld();ctx.restore();requestAnimationFrame(draw)}
function drawWorld(){let g=ctx.createLinearGradient(0,0,900,600);g.addColorStop(0,'#1d4a3e');g.addColorStop(1,'#12342f');ctx.fillStyle=g;ctx.fillRect(0,0,900,600); // moonlit patches
ctx.fillStyle='rgba(215,184,111,.05)';ctx.beginPath();ctx.arc(670,60,130,0,7);ctx.fill();
// pathways
ctx.fillStyle='#755f45';ctx.beginPath();ctx.moveTo(420,600);ctx.lineTo(500,600);ctx.lineTo(510,400);ctx.lineTo(470,270);ctx.lineTo(450,0);ctx.lineTo(385,0);ctx.lineTo(430,270);ctx.lineTo(445,400);ctx.closePath();ctx.fill();ctx.fillStyle='#8c7654';ctx.beginPath();ctx.moveTo(0,300);ctx.lineTo(900,280);ctx.lineTo(900,335);ctx.lineTo(0,350);ctx.closePath();ctx.fill();
// grass lines
ctx.strokeStyle='rgba(100,166,115,.28)';ctx.lineWidth=2;for(let i=0;i<60;i++){let x=(i*173)%900,y=(i*89)%570;ctx.beginPath();ctx.moveTo(x,y);ctx.lineTo(x-3,y-9);ctx.moveTo(x+2,y);ctx.lineTo(x+7,y-7);ctx.stroke()}
// gates and hut
ctx.fillStyle='#173b34';ctx.fillRect(370,0,160,50);ctx.fillStyle='#ba8c55';ctx.fillRect(395,3,7,48);ctx.fillRect(498,3,7,48);ctx.strokeStyle='#d2a266';ctx.lineWidth=3;ctx.strokeRect(382,5,136,42);ctx.fillStyle='#d9b677';ctx.font='bold 11px DM Sans';ctx.textAlign='center';ctx.fillText('LA LOMA',450,27);drawHut(770,510);drawTree(74,76,1.3);drawTree(830,75,1);drawTree(70,520,.9);drawTree(836,515,1.15);
// graves
[[145,264,'M'],[240,265,'R'],[590,262,'L'],[770,250,'S'],[120,430,'C'],[390,370,'A'],[570,433,'T'],[820,365,'V']].forEach((a,i)=>grave(...a,i%3===0));spots.forEach(drawSpot);drawPlayer();}
function drawTree(x,y,s){ctx.save();ctx.translate(x,y);ctx.scale(s,s);ctx.fillStyle='#654733';ctx.fillRect(-6,12,12,38);ctx.fillStyle='#1d5b44';ctx.beginPath();ctx.arc(-17,4,22,0,7);ctx.arc(8,-5,29,0,7);ctx.arc(23,13,20,0,7);ctx.fill();ctx.fillStyle='#2d7854';ctx.beginPath();ctx.arc(0,-12,20,0,7);ctx.fill();ctx.restore()}
function drawHut(x,y){ctx.fillStyle='#744b36';ctx.fillRect(x-55,y-53,110,53);ctx.fillStyle='#4d352b';ctx.beginPath();ctx.moveTo(x-70,y-50);ctx.lineTo(x,y-92);ctx.lineTo(x+70,y-50);ctx.closePath();ctx.fill();ctx.fillStyle='#d19a61';ctx.fillRect(x-10,y-37,20,37);ctx.fillStyle='#a9c1a0';ctx.fillRect(x+23,y-38,17,14);ctx.fillStyle='#e7bb67';ctx.font='9px DM Sans';ctx.textAlign='center';ctx.fillText('DESCANSO',x,y+16)}
function grave(x,y,letter,flower){ctx.fillStyle='#a4a89a';ctx.beginPath();ctx.roundRect(x-19,y-27,38,38,13);ctx.fill();ctx.fillStyle='#717b70';ctx.fillRect(x-24,y+9,48,7);ctx.fillStyle='#57645c';ctx.font='bold 11px serif';ctx.textAlign='center';ctx.fillText(letter,x,y-5);if(flower){ctx.fillStyle='#e28b70';ctx.beginPath();ctx.arc(x+26,y+1,4,0,7);ctx.arc(x+32,y+4,4,0,7);ctx.fill();ctx.fillStyle='#65a66d';ctx.fillRect(x+28,y+5,3,15)}}
function drawSpot(s){if(s.done)return;let pulse=2+Math.sin(Date.now()/280+s.x)*3;ctx.globalAlpha=.18;ctx.fillStyle=s.type==='candle'?'#f2c56e':'#8bd0a9';ctx.beginPath();ctx.arc(s.x,s.y,24+pulse,0,7);ctx.fill();ctx.globalAlpha=1;ctx.font='22px serif';ctx.textAlign='center';ctx.fillText(s.emoji,s.x,s.y+8);ctx.fillStyle='#e6d5aa';ctx.font='10px DM Sans';ctx.fillText(s.label,s.x,s.y+29)}
function drawPlayer(){ctx.save();ctx.translate(state.x,state.y);ctx.fillStyle='rgba(0,0,0,.25)';ctx.beginPath();ctx.ellipse(0,17,17,7,0,0,7);ctx.fill();ctx.fillStyle='#d98867';ctx.beginPath();ctx.arc(0,-8,12,0,7);ctx.fill();ctx.fillStyle='#205847';ctx.beginPath();ctx.arc(0,-14,14,Math.PI,0);ctx.fill();ctx.fillStyle='#e5b968';ctx.fillRect(-9,6,18,18);ctx.fillStyle='#0b2823';ctx.fillRect(-12,23,9,5);ctx.fillRect(3,23,9,5);ctx.restore()}
function update(t){let dt=Math.min(.04,(t-last)/1000||0);last=t;let dx=(keys.right?1:0)-(keys.left?1:0),dy=(keys.down?1:0)-(keys.up?1:0);if(dx||dy){let len=Math.hypot(dx,dy);state.x+=dx/len*state.speed*60*dt;state.y+=dy/len*state.speed*60*dt;state.x=Math.max(26,Math.min(874,state.x));state.y=Math.max(65,Math.min(550,state.y))}for(const s of spots){if(!s.done&&Math.hypot(state.x-s.x,state.y-s.y)<40){showToast('Toca aquí para '+(s.type==='candle'?'encender la vela':'cuidar este rincón'));}}}
function interact(){let target=spots.find(s=>!s.done&&Math.hypot(state.x-s.x,state.y-s.y)<52);if(!target){if(Math.hypot(state.x-770,state.y-510)<70){state.energy=state.maxEnergy;updateUI();showToast('Energía recuperada ✦');}return}if(state.energy<=0){showToast('Necesitas descansar primero');return}target.done=true;state.energy--;if(target.type==='candle')state.quest++;state.xp+=target.type==='candle'?25:15;state.coins+=target.type==='clean'?3:1;state.respect+=1;if(state.xp>=100){state.level++;state.xp-=100;state.maxEnergy++;state.energy=state.maxEnergy;showToast('¡Subiste al nivel '+state.level+'! ✦')}else showToast(target.type==='candle'?'La luz queda encendida. Gracias.':'El rincón vuelve a respirar. +XP');updateUI()}
function showToast(t){let el=document.getElementById('toast');el.textContent=t;el.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('show'),2100)}
function updateUI(){document.getElementById('energyText').textContent=state.energy+' / '+state.maxEnergy;document.getElementById('energyBar').style.width=state.energy/state.maxEnergy*100+'%';document.getElementById('xpText').textContent=state.xp+' / 100 XP';document.getElementById('xpBar').style.width=state.xp+'%';document.getElementById('levelText').textContent=state.level;document.getElementById('coinText').textContent=state.coins;document.getElementById('respectText').textContent=state.respect;document.getElementById('questText').textContent=state.quest+' / 3 velas';document.getElementById('questBar').style.width=Math.min(100,state.quest/3*100)+'%';if(state.quest>=3){document.querySelector('.mission-card h2').textContent='¡La noche está protegida!';document.querySelector('.mission-card p').textContent='Las ánimas tienen una luz que seguir. Vuelve mañana para otro encargo.'}renderItems()}
function renderItems(){let html=Object.entries(state.items).map(([e,n])=>`<div class="item"><span>${e}</span><small>${n}</small></div>`).join('');document.getElementById('quickItems').innerHTML=html;document.getElementById('fullItems').innerHTML=html}
function modal(id,open){document.getElementById(id).classList.toggle('hidden',!open)}
addEventListener('resize',resize);addEventListener('keydown',e=>{keys[e.key.toLowerCase()]=true;if(e.key===' '||e.key==='Enter')interact()});addEventListener('keyup',e=>keys[e.key.toLowerCase()]=false);document.querySelectorAll('[data-key]').forEach(b=>{let k=b.dataset.key;b.addEventListener('pointerdown',e=>{e.preventDefault();keys[k]=true});['pointerup','pointerleave','pointercancel'].forEach(ev=>b.addEventListener(ev,()=>keys[k]=false))});canvas.addEventListener('pointerdown',e=>{let r=canvas.getBoundingClientRect(),tx=(e.clientX-r.left)/r.width*900,ty=(e.clientY-r.top)/r.height*600;let target=spots.find(s=>!s.done&&Math.hypot(tx-s.x,ty-s.y)<55);if(target){state.x=target.x;state.y=target.y;interact()}else{state.x=Math.max(25,Math.min(875,tx));state.y=Math.max(60,Math.min(550,ty))}});document.addEventListener('click',e=>{let tab=e.target.closest('[data-tab]');if(tab){document.querySelectorAll('.bottom-nav button').forEach(b=>b.classList.remove('active'));tab.classList.add('active');let id=tab.dataset.tab;if(id==='bag')modal('inventoryModal',true);if(id==='journal')modal('journalModal',true);if(id==='help')modal('helpModal',true)}if(e.target.id==='openInventory')modal('inventoryModal',true);if(e.target.id==='closeInventory'||e.target.classList.contains('close')){e.target.closest('.modal').classList.add('hidden')}});setInterval(update,16);resize();renderItems();updateUI();requestAnimationFrame(draw);

